          maxLength: 20
          example: '+61412345678'
        email:
          title: Email address
          description: >-
            The optional email address of the pet owner. When present it must be a syntactically
            valid address; it is stored and returned lower-cased.
          type: string
          format: email
          maxLength: 255
          example: 'george.franklin@example.com'
        registrationDate:
          title: Registration date
          description: >-
            The date the owner registered with the clinic. On create, when omitted it defaults to
            the server's current date.
          type: string
          format: date
          example: '2020-06-15'
        sharesHousehold:
          title: Shares household
          description: >-
            Set to true on create to allow the owner even though another owner already has the
            same last name and address (compared case-insensitively with collapsed whitespace).
            Otherwise such a create is rejected with 409 Conflict. Not stored.
          type: boolean
          writeOnly: true
          example: false
      required:
        - firstName
        - lastName
        - address
        - city
        - telephone
    Owner:
      title: Owner
      description: A pet owner.
      allOf:
        - $ref: '#/components/schemas/OwnerFields'
        - type: object
          properties:
            id:
              title: ID
              description: The ID of the pet owner.
              type: integer
              format: int32
              minimum: 0
              example: 1
              readOnly: true
            pets:
              title: Pets
              description: The pets owned by this individual including any booked vet visits.
              type: array
              items:
                $ref: '#/components/schemas/Pet'
              readOnly: true
            displayName:
              title: Display name
              description: The owner's name formatted as 'LastName, FirstName' from the stored names.
              type: string
              example: 'Franklin, George'
              readOnly: true
            initials:
              title: Initials
              description: The upper-cased first letters of the owner's first and last names, dot-separated with a trailing dot.
              type: string
              example: 'G.F.'
              readOnly: true
            customerCode:
              title: Customer code
              description: >-
                Assigned on create as '<LAST3>-<NNNN>': the upper-cased first three letters of the
                last name, a dash, and a global 4-digit zero-padded sequence equal to one more than
                the number of owners existing at creation time.
              type: string
              example: 'FRA-0011'
              readOnly: true
          required:
            - pets
    OwnerPage:
      title: Owner page
      description: A page of pet owners.
      type: object
      properties:
        content:
          title: Content
